-- Migration 0007 (Phase 08C, ADR 0019): bot foundation. Generated by drizzle-kit, then edited by hand in three marked places:
-- this preflight, one moved constraint, and the functions and triggers appended at the end (Drizzle models neither).
--
-- Preflight 1: bot configurations are stored as canonical UTF-8 JSON text whose byte length IS the flow-contract limit
-- (65,536 bytes, ADR 0017). In any other server encoding octet_length() would measure something else, so refuse.
DO $$
BEGIN
	IF current_setting('server_encoding') <> 'UTF8' THEN
		RAISE EXCEPTION 'migration 0007 refused: the server encoding is %, but bot configurations need UTF8', current_setting('server_encoding');
	END IF;
END $$;
--> statement-breakpoint
-- Preflight 2: adding a column and a unique constraint to "conversations" needs table locks. Fail fast instead of queueing
-- behind live traffic (and blocking it); run the migration in a planned window. LOCAL: ends with the migration transaction.
SET LOCAL lock_timeout = '5s';
