-- ===================================================================================================================
-- Hand-written (Drizzle does not model functions or triggers). Every rule below is a database guarantee, not an application
-- convention: it holds for every writer, including raw SQL.
-- ===================================================================================================================
--
-- Conversation control sequence (V3.2 J.1, K.10). The ONLY writer of conversations.control_seq. The UPDATE takes the
-- conversation row lock until commit, so values follow commit order per conversation, and a rolled-back allocation leaves
-- nothing behind. It touches no other column (updated_at, last_message_at and Inbox ordering are unchanged). Raises if the
-- conversation does not exist in that organization, so no row is ever written without a sequence.
CREATE FUNCTION allocate_conversation_control_seq(p_organization_id uuid, p_conversation_id uuid) RETURNS bigint LANGUAGE plpgsql AS $$
DECLARE
	v bigint;
BEGIN
	UPDATE "conversations" SET control_seq = control_seq + 1
	 WHERE organization_id = p_organization_id AND id = p_conversation_id
	RETURNING control_seq INTO v;
	IF v IS NULL THEN
		RAISE EXCEPTION 'allocate_conversation_control_seq: no such conversation in this organization' USING ERRCODE = 'foreign_key_violation';
	END IF;
	RETURN v;
END $$;
--> statement-breakpoint
-- Drafts (bots). The draft is canonical JSON text (ADR 0019): it must parse as JSON (json, not jsonb: jsonb refuses \u0000,
-- which an unfinished draft may still contain). A draft change increments draft_revision by exactly 1 (the service's
-- compare-and-set is backed here) and is stamped with the database clock; a draft is never removed.
CREATE FUNCTION bots_guard() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
	IF TG_OP = 'INSERT' THEN
		IF NEW.draft_revision <> 0 THEN
			RAISE EXCEPTION 'bots: a new bot starts at draft revision 0' USING ERRCODE = 'check_violation';
		END IF;
		IF NEW.draft_config_canonical IS NOT NULL THEN
			PERFORM NEW.draft_config_canonical::json;
			NEW.draft_updated_at := clock_timestamp();
		END IF;
		RETURN NEW;
	END IF;
	IF NEW.id IS DISTINCT FROM OLD.id OR NEW.organization_id IS DISTINCT FROM OLD.organization_id
		OR NEW.created_by_membership_id IS DISTINCT FROM OLD.created_by_membership_id
		OR NEW.created_at IS DISTINCT FROM OLD.created_at THEN
		RAISE EXCEPTION 'bots: a bot never changes its identity, organization or creator' USING ERRCODE = 'check_violation';
	END IF;
	IF NEW.draft_config_canonical IS DISTINCT FROM OLD.draft_config_canonical THEN
		IF NEW.draft_config_canonical IS NULL THEN
			RAISE EXCEPTION 'bots: a draft is never removed' USING ERRCODE = 'check_violation';
		END IF;
		IF NEW.draft_revision IS DISTINCT FROM OLD.draft_revision + 1 THEN
			RAISE EXCEPTION 'bots: a draft change increments draft_revision by exactly 1' USING ERRCODE = 'check_violation';
		END IF;
		PERFORM NEW.draft_config_canonical::json;
		NEW.draft_updated_at := clock_timestamp();
	ELSIF NEW.draft_revision IS DISTINCT FROM OLD.draft_revision
		OR NEW.draft_updated_at IS DISTINCT FROM OLD.draft_updated_at
		OR NEW.draft_updated_by_membership_id IS DISTINCT FROM OLD.draft_updated_by_membership_id THEN
		RAISE EXCEPTION 'bots: draft metadata changes only together with the draft' USING ERRCODE = 'check_violation';
	END IF;
	RETURN NEW;
END $$;
--> statement-breakpoint
CREATE TRIGGER bots_guard_trg BEFORE INSERT OR UPDATE ON "bots" FOR EACH ROW EXECUTE FUNCTION bots_guard();
--> statement-breakpoint
-- Published versions (V3.2 K.2). Insert only, and only when the jsonb equals the canonical text, the hash is the SHA-256 of
-- the canonical text's UTF-8 bytes and the schema version matches the configuration. Never updated or deleted.
CREATE FUNCTION bot_versions_guard() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
	IF TG_OP <> 'INSERT' THEN
		RAISE EXCEPTION 'bot_versions: a published version is immutable: % is not allowed', TG_OP USING ERRCODE = 'check_violation';
	END IF;
	IF NEW.config IS DISTINCT FROM NEW.config_canonical::jsonb THEN
		RAISE EXCEPTION 'bot_versions: config does not equal its canonical text' USING ERRCODE = 'check_violation';
	END IF;
	IF NEW.config_sha256 IS DISTINCT FROM encode(sha256(convert_to(NEW.config_canonical, 'UTF8')), 'hex') THEN
		RAISE EXCEPTION 'bot_versions: config_sha256 is not the SHA-256 of the canonical text' USING ERRCODE = 'check_violation';
	END IF;
	IF NEW.schema_version::text IS DISTINCT FROM (NEW.config ->> 'schemaVersion') THEN
		RAISE EXCEPTION 'bot_versions: schema_version does not match the configuration' USING ERRCODE = 'check_violation';
	END IF;
	NEW.published_at := clock_timestamp();
	RETURN NEW;
END $$;
--> statement-breakpoint
CREATE TRIGGER bot_versions_guard_trg BEFORE INSERT OR UPDATE OR DELETE ON "bot_versions" FOR EACH ROW EXECUTE FUNCTION bot_versions_guard();
--> statement-breakpoint
-- Deployments (V3.2 F.2, K.3). Inserted ACTIVE at epoch 1. The binding (organization, account, bot) never changes; the epoch
-- never decreases and rises by exactly 1, and must rise when the status becomes STOPPED or RETIRED; RETIRED is terminal and
-- immutable; nothing is deleted. The database stamps status_changed_at on every status change and start_eligible_from on
-- every activation or resume.
CREATE FUNCTION bot_deployments_guard() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
	IF TG_OP = 'DELETE' THEN
		RAISE EXCEPTION 'bot_deployments: a deployment is never deleted (retire it)' USING ERRCODE = 'check_violation';
	END IF;
	IF TG_OP = 'INSERT' THEN
		IF NEW.status <> 'ACTIVE' OR NEW.send_epoch <> 1 THEN
			RAISE EXCEPTION 'bot_deployments: a deployment starts ACTIVE at epoch 1' USING ERRCODE = 'check_violation';
		END IF;
		NEW.start_eligible_from := clock_timestamp();
		NEW.status_changed_at := NEW.start_eligible_from;
		NEW.activated_at := NEW.start_eligible_from;
		RETURN NEW;
	END IF;
	IF OLD.status = 'RETIRED' THEN
		RAISE EXCEPTION 'bot_deployments: a RETIRED deployment is immutable' USING ERRCODE = 'check_violation';
	END IF;
	IF NEW.id IS DISTINCT FROM OLD.id OR NEW.organization_id IS DISTINCT FROM OLD.organization_id
		OR NEW.whatsapp_account_id IS DISTINCT FROM OLD.whatsapp_account_id OR NEW.bot_id IS DISTINCT FROM OLD.bot_id
		OR NEW.activated_at IS DISTINCT FROM OLD.activated_at OR NEW.created_at IS DISTINCT FROM OLD.created_at THEN
		RAISE EXCEPTION 'bot_deployments: the binding of a deployment never changes' USING ERRCODE = 'check_violation';
	END IF;
	IF NEW.send_epoch < OLD.send_epoch OR NEW.send_epoch > OLD.send_epoch + 1 THEN
		RAISE EXCEPTION 'bot_deployments: send_epoch never decreases and rises by exactly 1' USING ERRCODE = 'check_violation';
	END IF;
	IF NEW.status IS DISTINCT FROM OLD.status THEN
		IF NEW.status IN ('STOPPED', 'RETIRED') AND NEW.send_epoch <> OLD.send_epoch + 1 THEN
			RAISE EXCEPTION 'bot_deployments: stopping or retiring a deployment bumps send_epoch' USING ERRCODE = 'check_violation';
		END IF;
		NEW.status_changed_at := clock_timestamp();
		IF NEW.status = 'ACTIVE' THEN
			NEW.start_eligible_from := NEW.status_changed_at;
		ELSE
			NEW.start_eligible_from := OLD.start_eligible_from;
		END IF;
	ELSE
		NEW.status_changed_at := OLD.status_changed_at;
		NEW.start_eligible_from := OLD.start_eligible_from;
	END IF;
	RETURN NEW;
END $$;
--> statement-breakpoint
CREATE TRIGGER bot_deployments_guard_trg BEFORE INSERT OR UPDATE OR DELETE ON "bot_deployments" FOR EACH ROW EXECUTE FUNCTION bot_deployments_guard();
--> statement-breakpoint
-- Privacy retention (V3.2 K.11; owner-approved development default: 30 days after ended_at). The guard and the redaction
-- function both read this one function, so they cannot disagree. Changing the period is a reviewed migration that replaces it.
CREATE FUNCTION bot_session_redaction_after() RETURNS interval LANGUAGE sql STABLE AS $$ SELECT interval '30 days' $$;
--> statement-breakpoint
-- Sessions (V3.1 rules, V3.2 K.5 and K.11). Runs BEFORE the control-sequence allocation (triggers fire in name order:
-- bot_sessions_a_guard_trg, then bot_sessions_b_allocate_*); it leaves the allocator-owned columns to the allocator, and the
-- table CHECKs validate the final row.
--  INSERT: live, with no end, notice, suppression, handover or redaction fields; started_at stamped by the database.
--  live row: ownership, version, deployment and start never change; revision rises by exactly 1; output_suppressed_at is set
--    once; redacted_at stays NULL; the move to a terminal state stamps ended_at with the database clock (so retention can
--    never be shortened by backdating), and is the only update in which terminal_notice_step_seq may become non-NULL (the
--    CHECK requires a terminal state).
--  terminal row: unchanged, except the exactly shaped one-way redaction after the retention period (whole-row comparison).
CREATE FUNCTION bot_sessions_guard() RETURNS trigger LANGUAGE plpgsql AS $$
DECLARE
	probe "bot_sessions";
BEGIN
	IF TG_OP = 'DELETE' THEN
		RAISE EXCEPTION 'bot_sessions: a session is never deleted' USING ERRCODE = 'check_violation';
	END IF;
	IF TG_OP = 'INSERT' THEN
		IF NEW.state NOT IN ('ACTIVE', 'WAITING_FOR_SEND', 'WAITING_FOR_INPUT') THEN
			RAISE EXCEPTION 'bot_sessions: a session is inserted in a live state' USING ERRCODE = 'check_violation';
		END IF;
		IF NEW.terminal_notice_step_seq IS NOT NULL OR NEW.redacted_at IS NOT NULL OR NEW.ended_at IS NOT NULL
			OR NEW.end_reason IS NOT NULL OR NEW.handover_reason IS NOT NULL OR NEW.handover_control_seq IS NOT NULL
			OR NEW.output_suppressed_at IS NOT NULL THEN
			RAISE EXCEPTION 'bot_sessions: a new session has no end, notice, handover, suppression or redaction' USING ERRCODE = 'check_violation';
		END IF;
		NEW.started_at := clock_timestamp();
		RETURN NEW;
	END IF;

	IF OLD.state IN ('ACTIVE', 'WAITING_FOR_SEND', 'WAITING_FOR_INPUT') THEN
		IF NEW.id IS DISTINCT FROM OLD.id OR NEW.organization_id IS DISTINCT FROM OLD.organization_id
			OR NEW.bot_id IS DISTINCT FROM OLD.bot_id OR NEW.bot_version_id IS DISTINCT FROM OLD.bot_version_id
			OR NEW.deployment_id IS DISTINCT FROM OLD.deployment_id
			OR NEW.whatsapp_account_id IS DISTINCT FROM OLD.whatsapp_account_id
			OR NEW.contact_id IS DISTINCT FROM OLD.contact_id OR NEW.conversation_id IS DISTINCT FROM OLD.conversation_id
			OR NEW.started_by_message_id IS DISTINCT FROM OLD.started_by_message_id
			OR NEW.started_control_seq IS DISTINCT FROM OLD.started_control_seq
			OR NEW.started_at IS DISTINCT FROM OLD.started_at THEN
			RAISE EXCEPTION 'bot_sessions: a session never changes its owner, conversation, version, deployment or start' USING ERRCODE = 'check_violation';
		END IF;
		IF NEW.redacted_at IS NOT NULL THEN
			RAISE EXCEPTION 'bot_sessions: a live session cannot be redacted' USING ERRCODE = 'check_violation';
		END IF;
		IF OLD.output_suppressed_at IS NOT NULL AND NEW.output_suppressed_at IS DISTINCT FROM OLD.output_suppressed_at THEN
			RAISE EXCEPTION 'bot_sessions: output_suppressed_at is set once and never changed' USING ERRCODE = 'check_violation';
		END IF;
		IF NEW.revision IS DISTINCT FROM OLD.revision + 1 THEN
			RAISE EXCEPTION 'bot_sessions: every change of a live session increments revision by exactly 1' USING ERRCODE = 'check_violation';
		END IF;
		IF NEW.state IN ('COMPLETED', 'HANDED_OVER', 'FAILED') THEN
			NEW.ended_at := clock_timestamp();
		END IF;
		RETURN NEW;
	END IF;

	-- OLD is terminal.
	IF NEW IS NOT DISTINCT FROM OLD THEN
		RETURN NEW;
	END IF;
	IF OLD.redacted_at IS NOT NULL THEN
		RAISE EXCEPTION 'bot_session_redacted' USING ERRCODE = 'check_violation';
	END IF;
	probe := NEW;
	probe.variables := OLD.variables;
	probe.awaiting := OLD.awaiting;
	probe.awaiting_token := OLD.awaiting_token;
	probe.last_consumed_token := OLD.last_consumed_token;
	probe.redacted_at := OLD.redacted_at;
	IF probe IS DISTINCT FROM OLD THEN
		RAISE EXCEPTION 'bot_session_terminal_immutable' USING ERRCODE = 'check_violation';
	END IF;
	IF NEW.redacted_at IS NULL OR NEW.variables IS DISTINCT FROM '{}'::jsonb OR NEW.awaiting IS NOT NULL
		OR NEW.awaiting_token IS NOT NULL OR NEW.last_consumed_token IS NOT NULL THEN
		RAISE EXCEPTION 'bot_session_redaction_incomplete' USING ERRCODE = 'check_violation';
	END IF;
	IF OLD.ended_at IS NULL OR OLD.ended_at > clock_timestamp() - bot_session_redaction_after() THEN
		RAISE EXCEPTION 'bot_session_redaction_not_eligible' USING ERRCODE = 'check_violation';
	END IF;
	NEW.redacted_at := clock_timestamp();
	RETURN NEW;
END $$;
--> statement-breakpoint
CREATE TRIGGER bot_sessions_a_guard_trg BEFORE INSERT OR UPDATE OR DELETE ON "bot_sessions" FOR EACH ROW EXECUTE FUNCTION bot_sessions_guard();
--> statement-breakpoint
-- Control-sequence allocation for sessions (K.10): the session start, and the live -> HANDED_OVER transition (never a
-- redaction or any other terminal-row update). Application-supplied values are overwritten.
CREATE FUNCTION bot_sessions_allocate_control_seq() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
	IF TG_OP = 'INSERT' THEN
		NEW.started_control_seq := allocate_conversation_control_seq(NEW.organization_id, NEW.conversation_id);
	ELSE
		NEW.handover_control_seq := allocate_conversation_control_seq(NEW.organization_id, NEW.conversation_id);
	END IF;
	RETURN NEW;
END $$;
--> statement-breakpoint
CREATE TRIGGER bot_sessions_b_allocate_handover_trg BEFORE UPDATE ON "bot_sessions" FOR EACH ROW
	WHEN (OLD.state NOT IN ('COMPLETED', 'HANDED_OVER', 'FAILED') AND NEW.state = 'HANDED_OVER')
	EXECUTE FUNCTION bot_sessions_allocate_control_seq();
--> statement-breakpoint
CREATE TRIGGER bot_sessions_b_allocate_insert_trg BEFORE INSERT ON "bot_sessions" FOR EACH ROW EXECUTE FUNCTION bot_sessions_allocate_control_seq();
--> statement-breakpoint
-- The one sanctioned redaction (K.11): one statement, one organization, bounded, skipping rows another transaction holds. It
-- clears only the approved fields of terminal sessions past the retention period; the guard admits nothing else. It takes no
-- conversation, deployment, trigger or request lock, allocates no sequence, and writes no event. Called only by the 08F
-- retention job (pinned by a boundary test).
CREATE FUNCTION redact_expired_bot_sessions(p_organization_id uuid, p_limit integer) RETURNS integer LANGUAGE plpgsql AS $$
DECLARE
	n integer;
BEGIN
	IF p_organization_id IS NULL OR p_limit IS NULL OR p_limit < 1 OR p_limit > 10000 THEN
		RAISE EXCEPTION 'redact_expired_bot_sessions: an organization and a limit between 1 and 10000 are required' USING ERRCODE = 'invalid_parameter_value';
	END IF;
	WITH c AS (
		SELECT id FROM "bot_sessions"
		 WHERE organization_id = p_organization_id
		   AND state IN ('COMPLETED', 'HANDED_OVER', 'FAILED') AND redacted_at IS NULL
		   AND ended_at <= clock_timestamp() - bot_session_redaction_after()
		 ORDER BY ended_at, id
		 LIMIT p_limit
		 FOR UPDATE SKIP LOCKED
	), u AS (
		UPDATE "bot_sessions" s
		   SET variables = '{}'::jsonb, awaiting = NULL, awaiting_token = NULL, last_consumed_token = NULL,
		       redacted_at = clock_timestamp()
		  FROM c
		 WHERE s.organization_id = p_organization_id AND s.id = c.id
		RETURNING 1
	)
	SELECT count(*)::integer INTO n FROM u;
	RETURN n;
END $$;
--> statement-breakpoint
-- Deployment and session history is append-only.
CREATE FUNCTION bots_append_only() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
	RAISE EXCEPTION '% is append-only: % is not allowed', TG_TABLE_NAME, TG_OP USING ERRCODE = 'check_violation';
END $$;
--> statement-breakpoint
CREATE TRIGGER bot_deployment_events_append_only_trg BEFORE UPDATE OR DELETE ON "bot_deployment_events" FOR EACH ROW EXECUTE FUNCTION bots_append_only();
--> statement-breakpoint
CREATE TRIGGER bot_session_events_append_only_trg BEFORE UPDATE OR DELETE ON "bot_session_events" FOR EACH ROW EXECUTE FUNCTION bots_append_only();
